import{_ as t,o as a,a as i,a2 as o}from"./chunks/framework.DCcmcJcL.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"api/introduction.md","filePath":"api/introduction.md","lastUpdated":1789331268000}'),r={name:"api/introduction.md"};function n(s,e,l,p,h,c){return a(),i("div",null,e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Bagisto provides comprehensive API solutions to help developers integrate and extend the platform&#39;s functionality. Whether you&#39;re building mobile apps, third-party integrations, or headless commerce solutions, our APIs offer the flexibility and power you need.</p><div class="info custom-block"><p class="custom-block-title">Separate packages</p><p>Neither API is part of the Bagisto core repository. They are installed as Composer packages, <code>bagisto/rest-api</code> and <code>bagisto/graphql-api</code>, each with its own release line. Install the release that matches your Bagisto version; the packages&#39; own README files carry the exact version table and any install steps that change between releases, and the commands on the following pages are the ones those packages document.</p></div><h2 id="available-api-types" tabindex="-1">Available API Types <a class="header-anchor" href="#available-api-types" aria-label="Permalink to &quot;Available API Types&quot;">​</a></h2><h3 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to &quot;REST API&quot;">​</a></h3><p>The Bagisto REST API follows RESTful principles and provides complete access to CRUD operations across all Bagisto features. Perfect for:</p><ul><li><strong>Mobile Applications</strong> - Build native iOS/Android shopping apps</li><li><strong>Third-party Integrations</strong> - Connect with external systems and services</li><li><strong>Progressive Web Apps (PWA)</strong> - Create fast, app-like web experiences</li><li><strong>Custom Admin Interfaces</strong> - Build specialized admin tools</li></ul><p><strong>Key Features:</strong></p><ul><li>Full CRUD operations support</li><li>Built-in pagination for performance</li><li>Interactive Swagger documentation generated from the package</li><li>Laravel Sanctum authentication</li></ul><div class="tip custom-block"><p class="custom-block-title">Getting Started</p><p>New to REST APIs? Start with our <a href="./rest-api.html">REST API Guide</a> for installation steps and examples.</p></div><h3 id="graphql-api" tabindex="-1">GraphQL API <a class="header-anchor" href="#graphql-api" aria-label="Permalink to &quot;GraphQL API&quot;">​</a></h3><p>The Bagisto GraphQL API enables flexible, efficient data fetching with a single endpoint. Ideal for:</p><ul><li><strong>Headless Commerce</strong> - Power modern frontend frameworks</li><li><strong>Mobile Apps</strong> - Reduce bandwidth with precise data queries</li><li><strong>Custom Storefronts</strong> - Build unique shopping experiences</li></ul><p><strong>Key Features:</strong></p><ul><li>Single endpoint for all operations</li><li>Flexible query structure - fetch exactly what you need</li><li>Built on Laravel Lighthouse</li><li>Type-safe schema with introspection and a GraphiQL playground</li></ul><div class="tip custom-block"><p class="custom-block-title">Modern Development</p><p>GraphQL is perfect for modern frontend frameworks like React, Vue, and React Native. Check out our <a href="./graphql-api.html">GraphQL API Guide</a> to get started.</p></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>The two packages authenticate differently:</p><ul><li><strong>REST API</strong>: Laravel Sanctum bearer tokens, issued by the package&#39;s admin and customer login endpoints</li><li><strong>GraphQL API</strong>: JWT bearer tokens for customers and admins, with the session middleware kept on the endpoint so the guest cart works</li></ul><h2 id="agents-in-the-browser" tabindex="-1">Agents in the browser <a class="header-anchor" href="#agents-in-the-browser" aria-label="Permalink to &quot;Agents in the browser&quot;">​</a></h2><p>For an AI agent that acts inside the shopper&#39;s browser rather than against an API, the storefront declares its actions as <a href="./../ai/webmcp.html">WebMCP</a> tools. That needs no package and no token.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next?&quot;">​</a></h2><p>Ready to start building? Choose your preferred API approach:</p><ul><li>📚 <a href="./rest-api.html">REST API Documentation</a> - Traditional RESTful endpoints</li><li>⚡ <a href="./graphql-api.html">GraphQL API Documentation</a> - Modern query language</li></ul>',24)]))}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
